UPDATE learning_units
SET title='短 /ɪ/ 与长 /iː/',
    content_json='{"category":"短元音与长元音","title":"/ɪ/ 和 /iː/","description":"两者都是前元音，主要区别是声音长度、紧张度和嘴角展开程度。","phonemes":[{"phonemeId":"p_1","ipa":"/ɪ/","description":"短促放松，舌位稍低，嘴角自然。","mouth":{"type":"relaxed"},"audioUrl":null,"examples":["sit","ship","bit"]},{"phonemeId":"p_2","ipa":"/iː/","description":"更长更紧，舌位更高，嘴角略向两侧展开。","mouth":{"type":"smile"},"audioUrl":null,"examples":["seat","sheep","beat"]}],"audioPairs":[{"left":"sit","right":"seat","tip":"先听元音长度：sit 短，seat 长。"},{"left":"ship","right":"sheep","tip":"ship 嘴角放松，sheep 嘴角更展开。"}],"memoryTip":"先判断有没有拉长，再看嘴角是否展开。"}'
WHERE id='unit_compare_1';

